package com.krdevops.springai.service.e2e;
import org.springframework.stereotype.Service;
import java.util.LinkedHashMap; import java.util.Map; import java.util.List; import java.util.Collections;
@Service public class PipelineReleaseReadiness { public Readiness evaluate(Map<String,Boolean> gates){if(gates==null||gates.isEmpty())throw new IllegalArgumentException("Gate는 필수입니다."); Map<String,Boolean> normalized=new LinkedHashMap<>(); gates.forEach((key,value)->{if(key==null||key.isBlank())throw new IllegalArgumentException("Gate 이름은 필수입니다."); normalized.put(key,Boolean.TRUE.equals(value));}); return new Readiness(normalized.values().stream().allMatch(Boolean.TRUE::equals),normalized);} public record Readiness(boolean ready,Map<String,Boolean> gates){public Readiness{gates=Collections.unmodifiableMap(new LinkedHashMap<>(gates));} public List<String> failedGateNames(){return gates.entrySet().stream().filter(e->!Boolean.TRUE.equals(e.getValue())).map(Map.Entry::getKey).toList();}} }
